#!/usr/bin/env python3
"""retrieval-check: deterministic gate for the CONTEXTUAL RETRIEVAL surface
(route by corpus size, chunking, contextualization, hybrid search, reranking,
retrieval eval). Stdlib only, offline, free.
Canonical source (read in full 2026-11-18, Anthropic, "Introducing Contextual
Retrieval", 2024-09-19, https://www.anthropic.com/news/contextual-retrieval):
- Small knowledge base (<200,000 tokens, about 500 pages): skip retrieval,
  put the whole base in the prompt with prompt caching (latency >2x better,
  costs up to 90% lower). Retrieval is for corpora that outgrow the prompt.
- Traditional RAG destroys context: a chunk like "The company's revenue grew
  by 3%" does not say which company or which quarter, so it cannot be found
  or used. Fix at indexing time: prepend chunk-specific context (usually
  50-100 tokens, generated by a model that sees the whole document plus the
  chunk, answering only with the succinct context) to the chunk BEFORE
  embedding it (Contextual Embeddings) and BEFORE building the BM25 index
  (Contextual BM25). With prompt caching the one-time contextualization cost
  was $1.02 per million document tokens (800-token chunks, 8k documents).
- Hybrid: embeddings miss exact matches; BM25 catches unique identifiers and
  technical terms. Run both, combine and deduplicate with rank fusion.
- Metric: retrieval failure = 1 - recall@20 (share of relevant chunks missing
  from the top 20). Measured ladder: baseline 5.7% -> contextual embeddings
  3.7% (-35%) -> + contextual BM25 2.9% (-49%) -> + reranking 1.9% (-67%).
  Benefits stack; techniques are complements, not alternatives.
- Delivery: top-20 chunks beat top-10 and top-5 in their tests; passing the
  contextualized chunk and distinguishing context from chunk can help.
  Always run evals. Chunk boundaries/size/overlap, embedding model choice
  and a domain-customized contextualizer prompt (e.g. a glossary) all matter.
- Reranking: initial retrieval takes a wide pool (they used top 150), a
  reranker scores each chunk against the query, top-K (they used 20) goes to
  the model. It adds latency and cost, so the pool size is an experiment,
  not a default copied blind.
Exit 0=PASS, 1=FAIL.
"""
import json, sys
def check(d):
    f=[]
    dec=d.get("decision") or {}
    if not dec.get("decision_recorded"): f.append("CR-0 the retrieval surface is not recorded as a decided surface - how the model finds the user's context and the intervention library is left to whatever the code happens to do")
    if not dec.get("owner_recorded"): f.append("CR-0 no retrieval owner is recorded - nobody is named to keep the index, the failure rate and the reindexing honest")
    if not dec.get("canonical_source_recorded"): f.append("CR-0 the canonical source is not recorded (Anthropic Contextual Retrieval: size route, contextualize before both indexes, hybrid, rerank, measure 1-recall@20) - every surface invents its own way of fetching context")
    rte=d.get("route") or {}
    if not rte.get("corpus_size_measured_route_decided"): f.append("CR-1 the corpus size is not measured and the route is not decided by it (under ~200k tokens the whole base goes in the prompt with caching; retrieval only above that) - a tiny corpus pays retrieval's failure modes for nothing, or a huge one is stuffed into prompts")
    if not rte.get("chunking_policy_recorded"): f.append("CR-1 no chunking policy is recorded (chunk size, boundaries, overlap, chosen and tested) - chunking is where context is destroyed, and an unrecorded policy cannot be improved")
    if not rte.get("corpus_inventory_versioned"): f.append("CR-1 the corpus has no versioned inventory (which documents, which version, what changed) - a retrieval result cannot be reproduced or blamed on a corpus change")
    ctx=d.get("contextualization") or {}
    if not ctx.get("context_prepended_before_both_indexes"): f.append("CR-2 chunk-specific context is not prepended before BOTH indexes (embeddings and BM25) - a context-free chunk like 'revenue grew by 3%' names neither its subject nor its period and cannot be retrieved or used")
    if not ctx.get("context_generated_from_whole_document"): f.append("CR-2 the prepended context is not generated from the whole document plus the chunk (usually 50-100 tokens, succinct context only) - context written from the chunk alone re-states what the chunk already says")
    if not ctx.get("contextualizer_prompt_domain_customized"): f.append("CR-2 the contextualizer prompt is not customized to the domain (glossary and terms defined elsewhere in the corpus are not supplied) - the generic prompt misses exactly the vocabulary the users query with")
    hyb=d.get("hybrid") or {}
    if not hyb.get("embeddings_and_bm25_both_run"): f.append("CR-3 retrieval is not hybrid (embeddings for semantic matches AND BM25 for exact identifiers and terms) - embeddings alone miss the exact-match queries BM25 exists to catch")
    if not hyb.get("rank_fusion_and_dedup"): f.append("CR-3 the two result lists are not combined with rank fusion and deduplicated - one retriever's ranking silently overrides the other and duplicates waste the context window")
    if not hyb.get("top_k_chosen_by_own_eval"): f.append("CR-3 the number of chunks passed to the model is not chosen by the team's own eval (Anthropic found top-20 beat top-10 and top-5 on their corpora) - the count is a copied default or a guess")
    rer=d.get("reranking_delivery") or {}
    if not rer.get("reranker_stage_pool_measured"): f.append("CR-4 there is no reranking stage over a wide first-stage pool (Anthropic: top 150 rescored to top 20) with the pool size measured on own data - first-stage ordering, with all its misses, is what the model sees")
    if not rer.get("latency_cost_budget_measured"): f.append("CR-4 the latency and cost the reranker adds are not measured against a budget - reranking is either skipped for an unmeasured fear or added with an unmeasured bill")
    if not rer.get("context_distinguished_sources_carried"): f.append("CR-4 delivered chunks do not distinguish prepended context from chunk text and do not carry their source ids - the model cannot tell evidence from annotation, and a wrong retrieval cannot be traced to its source")
    ev=d.get("evaluation") or {}
    if not ev.get("failure_rate_measured_on_golden_set"): f.append("CR-5 retrieval failure is not measured as 1 - recall@K on the team's own golden query set - 'retrieval works' is a feeling, and a regression ships silently")
    if not ev.get("ablations_stack_measured"): f.append("CR-5 the stack is not ablated on own data (baseline vs contextual embeddings vs + contextual BM25 vs + reranking; Anthropic's ladder was -35% / -49% / -67%) - layers are kept or dropped without knowing which one earns its cost")
    if not ev.get("indexing_cost_prepaid_reindex_on_change"): f.append("CR-5 indexing cost is not disciplined (contextualization is a one-time per-document cost - Anthropic measured $1.02 per million document tokens with caching - run only on already-paid credit with no new payment or auto-reload, and changed documents are re-indexed while unchanged ones are not re-paid for)")
    return f
if __name__=="__main__":
    data=json.load(open(sys.argv[1])); fails=check(data)
    if fails:
        print(f"FAIL ({len(fails)}):")
        [print(" -",x) for x in fails]; sys.exit(1)
    print("PASS")
